python3 - <<'EOF'
import subprocess
def entries(ref):
    txt = subprocess.run(['git','show',f'{ref}:CHANGELOG.md'],capture_output=True,text=True).stdout
    # Unreleased section = from '## Unreleased' to next '## '
    i = txt.index('## Unreleased'); j = txt.index('\n## ', i+1)
    sec = txt[i:j]
    out=[]
    for line in sec.split('\n'):
        if line.startswith('- '): out.append(line[:80])
    return out
main_e = entries('origin/main')
head_e = entries('HEAD')
from collections import Counter
cm, ch = Counter(main_e), Counter(head_e)
print("only on HEAD (branch-added bullets):")
for e in head_e:
    if ch[e] > cm[e]: print(" +", e)
print("only on main (branch-removed):")
for e in main_e:
    if cm[e] > ch[e]: print(" -", e)
EOF

python3 - <<'EOF'
import subprocess, re
def text(ref):
    return subprocess.run(['git','show',f'{ref}:CHANGELOG.md'],capture_output=True,text=True).stdout
main, head = text('origin/main'), text('HEAD')

# generic inverse: mojibake = utf8 bytes decoded as cp1251. Build map for the
# chars that appear in the file, then rewrite main's text to clean UTF-8.
import collections
moji = {}
for ch in set(head) | set(main):
    if ord(ch) > 127:
        b = ch.encode('utf-8')
        try:
            m = b.decode('cp1251')
            if m != ch: moji[m] = ch
        except UnicodeDecodeError:
            pass
clean_main = main
for m, c in sorted(moji.items(), key=lambda kv: -len(kv[0])):
    clean_main = clean_main.replace(m, c)
left = sum(clean_main.count(m) for m in moji)
print("unmapped mojibake left in cleaned main:", left)

import difflib
diff = list(difflib.unified_diff(clean_main.split('\n'), head.split('\n'), lineterm='', n=0))
adds = [l[1:] for l in diff if l.startswith('+') and not l.startswith('+++')]
dels = [l[1:] for l in diff if l.startswith('-') and not l.startswith('---')]
print(f"residual diff after de-mojibaking main: +{len(adds)} / -{len(dels)} lines")
for l in adds[:40]: print("  +", l[:100])
for l in dels[:10]: print("  -", l[:100])
EOF

